	#minacoding #p5js #generativeart
 */

var numPoints = 50;
var iterations = 15;
var pts, circs;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	colorMode(HSB, 100);
	initScene()
}

function draw() {
	noFill();

	for (let i = 0; i < iterations; i++) {
		for (let c of circs) {
			const x = c.x + random(-5, 5);
			const y = c.y + random(-5, 5);
			const d = c.d *random(0.9, 1.1);
			stroke((c.x*c.y)%100+random(-10, 10), 75, 75);
			arc(x, y, d, d, random(TWO_PI), random(TWO_PI));
		}
	}

	// margin
	noStroke();
	fill("white");
	const m = max(width, height) * 0.075;
	rect(0, 0, width, m);
	rect(0, height-m, width, m);
	rect(0, 0, m, height);
	rect(width-m, 0, m, height);

	// noLoop() removed for animation
}

// init scene, define points and find circle positions
function initScene() {
	background(random(100), 15, 85);
	loop();

	// generate random points
	pts = [];
	for (let i = 0; i < numPoints; i++) {
		var x = random(width)
		var y = random(height)
		pts.push({
			x,
			y
		});
	}

	// generate circles for every nearest point
	circs = [];
	for (let p1 of pts) {
		let nearestp = null;
		let nearestd = Infinity;
		for (let p2 of pts) {
			if (p1 !== p2) {
				var d = dist(p1.x, p1.y, p2.x, p2.y);
				if (d < nearestd) {
					nearestp = p2;
					nearestd = d;
				}
			}
		}
		if (nearestp) {
			var x = lerp(p1.x, nearestp.x, 0.5);
			var y = lerp(p1.y, nearestp.y, 0.5);
			var d = nearestd;

			for (let c of circs) { // check for duplicates
				if (dist(x, y, c.x, c.y) < 0.01) nearestp = false;
			}

			if (nearestp) {
				circs.push({
					x,
					y,
					d
				});
			}
		}
	}
}

function mousePressed() {
	if (mouseButton === LEFT) initScene();
}
